use xiom.io;
enum Category {
  Food,
  Transport,
  Entertainment,
  Bills,
}

type Expense = {
  name: Str;
  amount: Int;
  category: Category;
}

type Tracker = {
  expenses: Vec[Expense];
  budget: Int;
}

fn cat_name(c: Category) -> Str {
  match c {
    Category.Food => "Food",
    Category.Transport => "Transport",
    Category.Entertainment => "Entertainment",
    Category.Bills => "Bills",
  }
}

fn add_expense(t: &mut Tracker, name: Str, amt: Int, cat: Category) {
  t.expenses.push(Expense{ name: name, amount: amt, category: cat });
}

fn total_spent(t: &Tracker) -> Int {
  var total = 0;
  var i = 0;
  while i < t.expenses.len() {
    total = total + t.expenses.get(i).unwrap().amount;
    i = i + 1;
  };
  total
}

fn category_total(t: &Tracker, cat: Category) -> Int {
  var sum = 0;
  var i = 0;
  while i < t.expenses.len() {
    let exp = t.expenses.get(i).unwrap();
    if exp.category == cat { sum = sum + exp.amount; };
    i = i + 1;
  };
  sum
}

fn check_budget(t: &Tracker) -> Str {
  let spent = total_spent(t);
  if spent > t.budget { return "OVER BUDGET!"; };
  if spent >= t.budget * 80 / 100 { return "WARNING: 80%+ used"; };
  "On track"
}

fn biggest_expense(t: &Tracker) -> Str {
  if t.expenses.len() == 0 { return "None"; };
  var big = t.expenses.get(0).unwrap();
  var i = 1;
  while i < t.expenses.len() {
    let exp = t.expenses.get(i).unwrap();
    if exp.amount > big.amount { big = exp; };
    i = i + 1;
  };
  big.name
}

fn main() -> Int {
  var tracker = Tracker{ expenses: Vec[Expense].new(), budget: 50000 };

  add_expense(&mut tracker, "Groceries", 8500, Category.Food);
  add_expense(&mut tracker, "Bus pass", 3500, Category.Transport);
  add_expense(&mut tracker, "Movie tickets", 2200, Category.Entertainment);
  add_expense(&mut tracker, "Electric bill", 9500, Category.Bills);
  add_expense(&mut tracker, "Lunch out", 1800, Category.Food);
  add_expense(&mut tracker, "Concert", 6000, Category.Entertainment);

  io.println(total_spent(&tracker).to_str());
  io.println(check_budget(&tracker));
  io.println(biggest_expense(&tracker));
  io.println((category_total(&tracker, Category.Food)).to_str());
  io.println((category_total(&tracker, Category.Entertainment)).to_str());

  return 0;
}
